    r = request.lower()
    if "refund" in r or "charge" in r:
        return "billing"
    if "error" in r or "login" in r:
        return "tech"
    if "price" in r or "buy" in r:
        return "sales"
    return "unknown"                     # nothing matched

HANDLERS = {
    "billing": lambda q: "billing agent handled it",
    "tech": lambda q: "tech agent handled it",
    "sales": lambda q: "sales agent handled it",
}

def route(request):
    label = classify(request)
    if label not in HANDLERS:            # validate + fallback
        return "general agent handled it"
    return HANDLERS[label](request)

