        return {"label": "tech", "confidence": 0.9}
    return {"label": "billing", "confidence": 0.4}   # unsure guess

def route(request, threshold=0.6):
    out = classify(request)
    if out["label"] not in LABELS or out["confidence"] < threshold:
        return "clarify: could you tell me more?"    # fallback
    return f"routed to {out['label']}"

