def route(request, classify, handlers, threshold=0.6, fallback=None):
    result = classify(request)
    label = result["label"]
    confidence = result["confidence"]
    # only dispatch a KNOWN label with sufficient confidence
    if label not in handlers or confidence < threshold:
        return fallback(request)
    return handlers[label](request)

