handlers = {
    "billing": lambda q: "billing",
    "tech": lambda q: "tech",
}
fallback = lambda q: "fallback"

# confident, known label -> dispatch
def c_ok(q):
    return {"label": "billing", "confidence": 0.9}
assert route("x", c_ok, handlers, fallback=fallback) == "billing"

# low confidence -> fallback
def c_low(q):
    return {"label": "tech", "confidence": 0.3}
assert route("x", c_low, handlers, fallback=fallback) == "fallback"

# unknown label -> fallback (never crash on a bad label)
def c_bad(q):
    return {"label": "marketing", "confidence": 0.99}
assert route("x", c_bad, handlers, fallback=fallback) == "fallback"
print("all tests passed")

