solution.code:
from typing import Callable

def route(request: str,
          classify: Callable,          # -> {"label": str, "confidence": float}
          handlers: dict,              # {label: fn(request) -> str}
          fallback: Callable,          # fn(request) -> str
          threshold: float = 0.6) -> str:
    result = classify(request)
    label = result["label"]
    confidence = result.get("confidence", 1.0)
    # validate against the closed set AND require enough confidence
    if label not in handlers or confidence < threshold:
        return fallback(request)
    return handlers[label](request)     # safe: label is known & confident

if __name__ == "__main__":
    handlers = {
        "billing": lambda q: "-> billing agent",
        "tech": lambda q: "-> tech agent",
    }
    fallback = lambda q: "-> general agent"
    def classify(q):
        if "refund" in q:
            return {"label": "billing", "confidence": 0.95}
        return {"label": "tech", "confidence": 0.3}   # unsure
    print(route("I need a refund", classify, handlers, fallback))
    print(route("hmm not sure", classify, handlers, fallback))
